/* Contenido de «IA para Freelancers y Consultores Independientes». Archivo generado con herramientas/dividir-catalogo.js: no se edita a mano. */
window.MARA_CONTENIDO("c-ia-freelance",{"l":{"c-ia-freelance-m1-l1":[{"tipo":"texto","texto":"El error más caro del freelancer no es cobrar barato: es decir «hago de todo». Cuando tu oferta es vaga, el cliente no sabe para qué buscarte, te compara con cualquiera y te regatea. Cuando es específica, te recuerda y te recomienda. La IA no sabe qué haces bien: tú se lo dices y ella te ayuda a ordenarlo y probar versiones."},{"tipo":"plantilla","rotulo":"Define tu oferta","texto":"Trabajo por mi cuenta como [profesión/oficio]. Esto es lo que sé hacer: [lista]. Mis últimos 5 trabajos fueron: [descríbelos]. Mis clientes suelen ser [tipo de negocio y tamaño]. Ayúdame a: 1) detectar en qué me repito (ahí está mi especialidad), 2) escribir 3 versiones de una frase de presentación de máximo 20 palabras, 3) decirme qué información me falta para que la frase sea creíble. No inventes logros ni cifras que no te di."},{"tipo":"comparar","titulo":"Tu presentación","malTitulo":"Vaga","mal":"«Soy diseñador gráfico freelance, hago logos, redes, páginas, presentaciones y lo que se ofrezca. Precios accesibles.»","bienTitulo":"Específica","bien":"«Diseño menús e imagen para restaurantes y cafeterías. En el último año armé la carta de 9 negocios en Guadalajara, lista para imprenta y para pantalla.»"},{"tipo":"relacionar","rotulo":"Tipo de cliente y lo que de verdad le duele","pares":[["Negocio familiar pequeño","No tiene tiempo ni quien le ayude con eso"],["Empresa mediana con área interna","Necesita manos extra en temporada alta"],["Startup o proyecto nuevo","Quiere arrancar rápido sin contratar a nadie"],["Agencia que subcontrata","Busca a alguien que cumpla fechas sin supervisión"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"La IA te propone poner «más de 200 clientes satisfechos» y tú llevas 18. Tú…","ops":["Lo corriges con tu número real","Lo dejas, suena mejor","Lo cambias por «más de 100», que suena menos exagerado"],"correcta":0},{"p":"Una oferta específica sirve sobre todo para…","ops":["Que te recuerden y te recomienden para eso","Que te contraten para cualquier cosa","Poder ofrecer muchos servicios distintos a la vez"],"correcta":0},{"p":"Tu especialidad la descubres viendo…","ops":["En qué trabajos te repites y te va bien","Lo que está de moda en internet","Lo que la IA te sugiera como lo más rentable"],"correcta":0}]},{"tipo":"reflexion","rotulo":"Tu frase de presentación","pregunta":"Escribe en una sola oración qué haces, para quién y con qué resultado. Sin adjetivos: «Hago ___ para ___ y con eso consiguen ___».","ayuda":"Hago… para… y con eso consiguen…"},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso:</b> Tania es traductora independiente en Monterrey. En su perfil dice «Traducciones de todo tipo, inglés y francés, precios accesibles». Revisando sus últimos 10 trabajos, 7 fueron manuales técnicos y fichas de seguridad para empresas de la industria de autopartes. La IA le propuso: «Traductora certificada con 15 años de experiencia en el sector automotriz». Tania tiene 6 años y no tiene certificación."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Cuál es la especialidad de Tania según sus datos?","ops":["Traducción literaria","Traducción técnica para la industria de autopartes","Traducción de todo tipo"],"correcta":1,"explica":"7 de 10 trabajos recientes apuntan a un nicho claro."},{"p":"¿Qué hace con la frase de la IA?","ops":["La publica, suena más profesional","Quita solo la palabra «certificada»","Corrige años y quita la certificación: solo publica lo que puede comprobar"],"correcta":2,"explica":"Inventar credenciales puede costarle clientes y, en algunos casos, problemas legales."},{"p":"¿Qué dato haría más creíble su presentación?","ops":["Un ejemplo real, con permiso del cliente, del tipo de documento que traduce","Un precio más bajo","Muchos adjetivos"],"correcta":0,"explica":"Evidencia concreta vale más que adjetivos."}]},{"tipo":"comparar","titulo":"El perfil de Tania","malTitulo":"Vago e inflado","mal":"«Traductora certificada con 15 años de experiencia en todo tipo de textos. Precios accesibles.»","bienTitulo":"Específico y real","bien":"«Traduzco manuales técnicos y fichas de seguridad del inglés al español para proveedores de autopartes. 6 años trabajando con plantas del norte del país.»"},{"tipo":"reflexion","rotulo":"Tus últimos 10 trabajos","pregunta":"Lista tus últimos 10 trabajos con tipo de cliente y tipo de entregable. Marca en qué te repites y escribe tu frase de presentación con solo datos comprobables.","ayuda":"1) … 2) … / Me repito en… / Mi frase: Hago… para…"},{"tipo":"clave","items":["Específico se recuerda; «hago de todo» se olvida.","Tu especialidad sale de tus últimos trabajos, no de la IA.","Nunca dejes que la IA invente cifras o logros tuyos."]}],"c-ia-freelance-m1-l2":[{"tipo":"texto","texto":"Muchos freelancers cobran «lo que cobraba el de antes» o lo que creen que el cliente aguanta. Así se trabaja mucho y se junta poco. Tu tarifa sale de tres datos tuyos: cuánto gastas al mes para trabajar, cuánto necesitas ganar y cuántas horas puedes <b>facturar</b> de verdad. Ojo: las horas facturables no son las 200 del mes; cotizar, cobrar, aprender y buscar clientes también toma tiempo y nadie te lo paga."},{"tipo":"excel","rotulo":"Tu tarifa por hora","datos":[["Concepto","Pesos"],["Gastos fijos del mes (internet, equipo, software, transporte)",9000],["Lo que necesitas ganar al mes",26000],["Horas facturables al mes",70],["Tarifa por hora",""],["Tarifa con 20% para imprevistos y vacaciones",""]],"retos":[{"celda":"B5","formula":"=(B2+B3)/B4","esperado":500,"texto":"<b>B5</b>: tarifa por hora = (gastos + lo que necesitas ganar) ÷ horas facturables."},{"celda":"B6","formula":"=REDONDEAR(B5*1.2,0)","esperado":600,"requiere":"REDONDEAR(","texto":"<b>B6</b>: la misma tarifa con 20% extra, redondeada sin decimales.","explica":"$600 por hora. Ese 20% cubre lo que nadie te paga: días sin trabajo, enfermedades, un cliente que se cae y las vacaciones que sí te vas a tomar."}]},{"tipo":"tabla","titulo":"Tres formas de cobrar","encabezados":["Forma","Cuándo conviene","Riesgo"],"filas":[["Por hora","Trabajos abiertos o de asesoría, donde no sabes cuánto tardarás","Al cliente le preocupa no saber el total; pide un tope"],["Por proyecto","Entregables claros y repetidos que ya sabes cuánto te toman","Si el alcance crece, tú pagas la diferencia"],["Por iguala mensual","Clientes que te necesitan seguido todo el mes","Se convierte en «disponible las 24 horas» si no defines qué incluye"]]},{"tipo":"plantilla","rotulo":"Sustentar tu precio sin bajarlo","texto":"Un cliente me dijo que mi precio de [monto] por [trabajo] está caro. Mi tarifa sale de estos datos: [pega tu cálculo]. Escríbeme una respuesta de máximo 6 renglones que: 1) no se disculpe ni baje el precio de golpe, 2) explique qué incluye el trabajo y qué no, 3) ofrezca una alternativa real (menos alcance por menos dinero, o pago en parcialidades). Tono amable y firme, español de México."},{"tipo":"completar","rotulo":"Completa tu criterio","instruccion":"Escribe una palabra en cada espacio.","items":[{"frase":"Las horas que dedico a cotizar y a buscar clientes NO son horas ___.","resp":["facturables","facturable","cobrables"],"pista":"Es el tipo de hora que sí le cobras a alguien."},{"frase":"Si el trabajo crece y cobré por proyecto, la diferencia la paga ___.","resp":["uno","yo","el freelancer","tú"],"pista":"Por eso el alcance se escribe antes de empezar."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Si bajas tus horas facturables de 70 a 50 al mes, tu tarifa por hora…","ops":["Sube","Baja","Se queda igual"],"correcta":0},{"p":"Cobrar por iguala sin decir qué incluye suele terminar en…","ops":["Trabajo ilimitado por el mismo dinero","Un cliente más ordenado","Menos trabajo por el mismo dinero"],"correcta":0}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso:</b> Óscar es fotógrafo de producto en León. Cobra $350 la hora «porque así cobraba su amigo». Gasta $7,000 al mes en equipo, software y transporte, necesita ganar $24,000 y, contando edición, cotizaciones y traslados, solo factura unas 55 horas al mes. Un cliente le ofrece una iguala de $8,000 al mes por «las fotos que se vayan necesitando»."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Cuál es la tarifa por hora con sustento de Óscar, sin colchón?","ops":["$350","Unos $564: (7,000 + 24,000) ÷ 55","$436: 24,000 ÷ 55"],"correcta":1,"explica":"Gastos más lo que necesita ganar, entre horas facturables: 31,000 ÷ 55 ≈ 564."},{"p":"¿Qué le falta a la oferta de iguala?","ops":["Nada, es dinero seguro","Que sea más alta","Definir cuántas sesiones o fotos incluye al mes, tiempos de entrega y qué se cobra aparte"],"correcta":2,"explica":"Una iguala sin límite se vuelve disponibilidad total por un monto fijo."},{"p":"Si la iguala incluye 20 horas al mes, ¿cuánto debería cobrar como mínimo con su tarifa sin colchón?","ops":["Unos $11,280","$8,000","$7,000"],"correcta":0,"explica":"20 × 564 ≈ 11,280. Con $8,000 estaría cobrando unos $400 por hora."}]},{"tipo":"relacionar","rotulo":"Situación y forma de cobro","pares":[["Asesoría abierta sin alcance claro","Por hora, con tope acordado"],["Sesión de 30 productos con fondo blanco que ya dominas","Por proyecto"],["Cliente que necesita fotos cada semana","Iguala con límite de sesiones"],["Proyecto nuevo que nunca has hecho","Por hora o por etapas, hasta conocer tus tiempos"]]},{"tipo":"clave","items":["Tarifa = (gastos + lo que necesitas ganar) ÷ horas facturables.","Agrega un colchón para huecos y vacaciones.","Por hora, por proyecto o por iguala: cada una tiene su riesgo."]}],"c-ia-freelance-m1-l3":[{"tipo":"texto","texto":"Los clientes no llegan solos y menos en el primer año. La prospección es una rutina, no una emergencia: cuando solo buscas clientes en los meses malos, siempre trabajas en meses malos. Aparta un bloque fijo a la semana (por ejemplo, martes de 9 a 11) y usa la IA para preparar mensajes, no para enviarlos por ti."},{"tipo":"plantilla","rotulo":"Mensaje de primer contacto","texto":"Quiero escribirle a [tipo de negocio] en [ciudad/zona]. Esto fue lo que vi de ellos: [algo concreto y real que observaste: su menú, su tienda en línea, su publicación]. Yo ofrezco [servicio] y he hecho [ejemplo real]. Escribe un mensaje de máximo 5 renglones para WhatsApp o correo que: mencione lo que observé, diga en una línea qué podría mejorar, proponga una llamada corta de 15 minutos y no suene a plantilla. Sin promesas de resultados ni cifras inventadas."},{"tipo":"comparar","titulo":"Mensaje en frío","malTitulo":"De copiar y pegar","mal":"«Hola, buen día. Ofrezco servicios de diseño, marketing digital, redes sociales y desarrollo web a precios accesibles. Quedo a sus órdenes para cualquier información.»","bienTitulo":"Con observación real","bien":"«Hola, vi que su carta en Facebook está en foto y se lee borrosa desde el celular. Hago menús para restaurantes; les puedo mandar una prueba de una página sin costo para que vean cómo se vería. ¿Le parece si platicamos 15 minutos el jueves?»"},{"tipo":"ordenar","rotulo":"Ordena tu rutina de prospección","items":[{"frase":"Listar investigar contactar seguimiento agendar","es":"De la lista de prospectos a la llamada agendada"}]},{"tipo":"plantilla","rotulo":"Tu caso de éxito para el portafolio","texto":"Convierte este trabajo que hice en un caso corto para mi portafolio: cliente [tipo de negocio, sin nombre si no tengo permiso], problema [cuál era], qué hice [pasos], resultado [dato real que sí puedo comprobar]. Formato: 4 párrafos cortos y un título. Si un dato no te lo di, escribe [PENDIENTE] en lugar de inventarlo."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Publicar el logo de un cliente en tu portafolio sin avisarle…","ops":["Conviene pedirle permiso antes","Es normal, ya te pagó","Está bien si solo lo publicas en tu cuenta personal"],"correcta":0},{"p":"El mejor momento para prospectar es…","ops":["Un bloque fijo cada semana, tengas o no trabajo","Cuando ya te quedaste sin proyectos","Solo al inicio de cada año"],"correcta":0},{"p":"Un mensaje en frío funciona mejor cuando…","ops":["Menciona algo concreto que viste del negocio","Enumera todos tus servicios","Incluye tu lista de precios completa"],"correcta":0}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso:</b> Rebeca hace contabilidad de redes para consultorios en Mérida. Le pidió a la IA 50 mensajes de primer contacto para mandar a una lista de consultorios que sacó de un directorio. La IA escribió 50 mensajes casi iguales que empiezan con «Estimado profesional de la salud» y prometen «triplicar sus pacientes en 30 días»."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Cuál es el problema principal de los mensajes?","ops":["Son muy cortos","No tienen ninguna observación real de cada consultorio y prometen un resultado que no puede garantizar","Están en español"],"correcta":1,"explica":"Suenan a plantilla y la promesa no es comprobable."},{"p":"¿Qué conviene más en su bloque de prospección de 2 horas?","ops":["Investigar 8 consultorios y escribir 8 mensajes con una observación concreta de cada uno","Mandar los 50 mensajes iguales","Esperar a que la busquen"],"correcta":0,"explica":"Pocos mensajes personalizados suelen responderse más que muchos genéricos."},{"p":"¿Qué hace con la promesa de «triplicar pacientes»?","ops":["La deja, llama la atención","La cambia por «duplicar»","La quita y habla de lo que sí hace, con un ejemplo real si lo tiene"],"correcta":2,"explica":"Nada de promesas de resultados ni cifras inventadas."}]},{"tipo":"comparar","titulo":"El mensaje de Rebeca","malTitulo":"Masivo","mal":"«Estimado profesional de la salud: le ayudamos a triplicar sus pacientes en 30 días con estrategias digitales.»","bienTitulo":"Con observación","bien":"«Hola, doctora. Vi que su página no tiene horario ni forma de agendar, y en sus reseñas dos pacientes lo mencionan. Ayudo a consultorios a publicar horarios y citas en línea. ¿Le parece si platicamos 15 minutos el martes?»"},{"tipo":"clave","items":["Prospectar es rutina semanal, no rescate de emergencia.","Una observación real vale más que una lista de servicios.","Pide permiso antes de mostrar el trabajo de un cliente."]}],"c-ia-freelance-m2-l1":[{"tipo":"texto","texto":"Una propuesta no es un catálogo de lo que sabes hacer: es un documento para que el cliente diga «sí» sin llamarte a preguntar. Las propuestas que se firman son cortas, dicen exactamente qué recibe el cliente, cuándo, cuánto cuesta y qué no incluye. La IA redacta bien esa estructura; el precio y las fechas los pones tú."},{"tipo":"plantilla","rotulo":"Propuesta en una página","texto":"Arma una propuesta de una página para este trabajo: cliente [tipo de negocio], problema que me contó [descríbelo con sus palabras], lo que voy a entregar [lista de entregables concretos], tiempo [semanas], precio [monto en pesos], forma de pago [anticipo y saldo], lo que NO incluye [lista]. Estructura: 1) lo que entendí de su necesidad, 2) qué entrego, 3) cómo trabajamos y en cuánto tiempo, 4) inversión y forma de pago, 5) qué no incluye, 6) vigencia de la propuesta y siguiente paso. Lenguaje sencillo, español de México, sin palabras rebuscadas."},{"tipo":"tabla","titulo":"Qué revisa el cliente (aunque no lo diga)","encabezados":["Sección","Lo que se pregunta","Qué debe encontrar"],"filas":[["Lo que entendí","¿Me escuchó?","Su problema con sus propias palabras"],["Entregables","¿Qué me van a dar exactamente?","Cosas contables: «3 videos de 30 segundos», no «contenido»"],["Tiempos","¿Cuándo lo tengo?","Fechas o semanas, y qué necesita de él"],["Inversión","¿Cuánto y cómo pago?","Monto, anticipo y saldo, vigencia"],["No incluye","¿Me van a cobrar extra después?","La lista clara, antes de firmar"]]},{"tipo":"destacado","texto":"<b>Entregables contables.</b> «Mejorar sus redes» no se puede entregar ni revisar. «12 publicaciones al mes, 4 con video de 30 segundos, calendario enviado el día 25» sí. Si no se puede contar, no se puede cerrar el proyecto… ni cobrar el saldo."},{"tipo":"relacionar","rotulo":"Lo que dice el cliente y lo que le faltó a tu propuesta","pares":[["«Déjame lo pienso y te aviso»","No hubo un siguiente paso ni fecha de vigencia"],["«¿Y eso incluye las fotos?»","Faltó la lista de lo que no incluye"],["«¿Cuándo estaría listo?»","No pusiste tiempos ni fechas"],["«Está muy caro»","No se ve el trabajo detrás del número"]]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Una propuesta sin fecha de vigencia…","ops":["Te deja atado a ese precio meses después","Es más profesional","Obliga al cliente a decidir más rápido"],"correcta":0},{"p":"«Manejo de redes sociales» como entregable es…","ops":["Imposible de medir y de cerrar","Perfectamente claro","Claro si el cliente ya te conoce"],"correcta":0},{"p":"La sección «no incluye» sirve para…","ops":["Evitar el pleito de después","Hacer la propuesta más larga","Subir el precio sin que el cliente lo note"],"correcta":0}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso:</b> Mauricio es desarrollador web en Querétaro. Una escuela de natación le pidió «una página bonita». Su propuesta de cuatro páginas explica tecnologías, metodologías ágiles y su trayectoria, y al final dice «Inversión: $18,000». No dice qué páginas lleva el sitio, si incluye textos y fotos, ni cuánto dura. La escuela contestó «déjame lo platico con mi socio»."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué le faltó a la propuesta de Mauricio?","ops":["Más tecnologías","Entregables contables, tiempos, qué no incluye, vigencia y siguiente paso","Más páginas"],"correcta":1,"explica":"El cliente no sabe qué recibe ni cuándo, así que no puede decir que sí."},{"p":"¿Cómo queda un entregable contable para este caso?","ops":["«Página bonita y moderna»","«Presencia digital completa»","«Sitio de 5 secciones (inicio, horarios, precios, galería, contacto con mapa), adaptado a celular»"],"correcta":2,"explica":"Se puede contar, revisar y cerrar."},{"p":"¿Qué debería decir la sección de qué no incluye?","ops":["Redacción de textos, fotografías, dominio y hospedaje, si no van incluidos","Nada, se ve mal","Todo lo que Mauricio no sabe hacer"],"correcta":0,"explica":"Justo lo que el cliente podría suponer incluido."}]},{"tipo":"completar","rotulo":"Completa la propuesta","instruccion":"Escribe la palabra que falta.","items":[{"frase":"Un entregable útil se puede ___: 5 secciones, 12 publicaciones, 3 videos.","resp":["contar","medir"],"pista":"Tiene número."},{"frase":"La propuesta cierra con la ___ del precio y el siguiente paso.","resp":["vigencia"],"pista":"Hasta cuándo es válida."},{"frase":"Lo que el cliente podría suponer incluido va en la sección de qué ___ incluye.","resp":["no"],"pista":"Dos letras."}]},{"tipo":"clave","items":["Una página, entregables contables, tiempos y precio.","Siempre una sección de qué NO incluye.","Vigencia y siguiente paso: el «lo pienso» se combate con fecha."]}],"c-ia-freelance-m2-l2":[{"tipo":"texto","texto":"Cotizar de memoria es la forma más rápida de trabajar gratis. Una cotización se arma sumando <b>horas estimadas × tu tarifa</b> más los gastos directos del proyecto (licencias, impresión, transporte, subcontratados). Estima siempre con tus horas reales de trabajos parecidos, no con las que te gustaría tardar."},{"tipo":"excel","rotulo":"Cotiza un proyecto","datos":[["Concepto","Pesos"],["Horas estimadas",45],["Tarifa por hora",600],["Honorarios",""],["Gastos directos (licencias, impresión)",3200],["Total del proyecto",""],["Anticipo del 50%",""]],"retos":[{"celda":"B4","formula":"=B2*B3","esperado":27000,"texto":"<b>B4</b>: honorarios = horas estimadas × tarifa por hora."},{"celda":"B6","formula":"=B4+B5","esperado":30200,"texto":"<b>B6</b>: total del proyecto = honorarios + gastos directos."},{"celda":"B7","formula":"=B6*0.5","esperado":15100,"texto":"<b>B7</b>: anticipo del 50%.","explica":"$15,100 antes de empezar. Ese anticipo no es desconfianza: paga las primeras semanas de tu trabajo y separa a los clientes serios de los que «luego te aviso»."}]},{"tipo":"plantilla","rotulo":"Redacta la cotización","texto":"Con estos números ya calculados por mí [pega el total, el anticipo y el saldo], escribe el texto de la cotización para [cliente]: concepto del trabajo, desglose en máximo 4 renglones, total, forma de pago (anticipo de [%] para iniciar y saldo contra entrega), vigencia de [días] y qué pasa si el proyecto se detiene por el cliente. No recalcules los montos: úsalos tal cual te los di."},{"tipo":"destacado","texto":"<b>Anticipo, siempre.</b> Un anticipo de entre 30% y 50% es práctica común entre independientes; el porcentaje exacto lo decides tú. La regla que sí es fija: nada de entregar los archivos finales antes de recibir el saldo. Acuérdalo por escrito desde la cotización y guarda el comprobante de cada pago. Sobre facturación e impuestos, pregúntale a tu contador: eso no se lo preguntes a la IA."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"La IA te calculó el total de la cotización y no revisaste. Eso es…","ops":["Riesgoso: el número lo calculas tú en la hoja","Práctico y suficiente","Aceptable si la cantidad se ve razonable"],"correcta":0},{"p":"Estimas las horas de un proyecto nuevo con base en…","ops":["Tus horas reales de trabajos parecidos","Lo que te gustaría tardar","Lo que tardó el freelancer anterior, según el cliente"],"correcta":0},{"p":"Entregar los archivos finales antes de cobrar el saldo…","ops":["Te deja sin nada que negociar si no pagan","Es señal de confianza","Obliga al cliente a pagar ese mismo día"],"correcta":0}]},{"tipo":"reflexion","rotulo":"Tu regla de anticipo","pregunta":"Escribe la regla que vas a usar de hoy en adelante: qué porcentaje pides de anticipo, en qué momento entregas y qué haces si el cliente pide empezar sin pagar.","ayuda":"Anticipo de… / Entrego cuando… / Si piden empezar sin pagar, yo…"},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso:</b> Lucía es ilustradora en la Ciudad de México. Le pidió a la IA «cotiza 12 ilustraciones para un libro infantil». La IA respondió con $6,000 en total «según precios promedio del mercado» y agregó «como persona física no necesitas facturar». Lucía sabe que cada ilustración le toma unas 5 horas y su tarifa es de $550."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Cuánto serían los honorarios con sus propios datos?","ops":["$6,000","$33,000: 12 × 5 × 550","$27,500"],"correcta":1,"explica":"60 horas por $550. La cifra de la IA no sale de ningún dato de Lucía."},{"p":"¿Qué hace con la afirmación sobre facturar?","ops":["La ignora y lo consulta con su contador: la IA no es fuente fiscal","La cree","La incluye en la cotización"],"correcta":0,"explica":"Las obligaciones fiscales dependen de su régimen y situación; las confirma su contador."},{"p":"¿Qué más debe llevar la cotización de un libro?","ops":["Nada más","Solo el total","Rondas de ajustes, formato de entrega, uso y derechos de las ilustraciones, anticipo y vigencia"],"correcta":2,"explica":"En ilustración, el uso y los derechos cambian el precio; se acuerdan por escrito."}]},{"tipo":"comparar","titulo":"La cotización de Lucía","malTitulo":"Hecha por la IA","mal":"«12 ilustraciones: $6,000 según precios promedio del mercado.»","bienTitulo":"Con sus números","bien":"«12 ilustraciones a color para libro infantil, 2 rondas de ajustes, archivos para imprenta. Honorarios: $33,000. Anticipo 40% para iniciar, saldo contra entrega de archivos finales. Vigencia: 15 días.»"},{"tipo":"clave","items":["Cotización = horas × tarifa + gastos directos.","Los números salen de la hoja de cálculo; la IA solo redacta.","Anticipo por escrito y archivos finales contra saldo."]}],"c-ia-freelance-m2-l3":[{"tipo":"texto","texto":"Casi ningún proyecto se pierde de golpe: se pierde de a poquito. «Ya que andas ahí, ¿me cambias el color?», «nada más una versión para Instagram», «¿le agregamos una sección?». Cada cosita se ve chiquita, pero juntas se comen tu ganancia. La solución no es pelear: es tener escrito, desde antes, qué incluye el proyecto y cuántas rondas de cambios trae."},{"tipo":"destacado","texto":"<b>El alcance se define antes, nunca después.</b> Dos frases en tu propuesta te ahorran meses de pleito: la lista de entregables contables y la frase «incluye N rondas de ajustes; cambios adicionales o de concepto se cotizan aparte». Ponlo en la propuesta, aunque el cliente sea tu conocido o tu primo."},{"tipo":"plantilla","rotulo":"Tu cláusula de alcance y cambios","texto":"Escribe el apartado de alcance y cambios para una propuesta de [tipo de proyecto]: 1) qué incluye (lista de entregables), 2) qué no incluye, 3) cuántas rondas de ajustes trae y qué cuenta como ajuste, 4) qué se considera cambio de concepto y se cotiza aparte, 5) qué pasa si el cliente se tarda en dar información o aprobaciones. Lenguaje claro y no amenazante, español de México. Aviso: si voy a usar esto como contrato, dime qué puntos conviene revisar con un abogado."},{"tipo":"ordenar","rotulo":"Ordena tu respuesta a un cambio fuera de alcance","items":[{"frase":"Escuchar confirmar recordar-alcance cotizar-aparte esperar-aprobación","es":"Del pedido del cliente al visto bueno por escrito"}]},{"tipo":"completar","rotulo":"Completa la regla","instruccion":"Escribe una palabra en cada espacio.","items":[{"frase":"Un cambio fuera de alcance no se discute: se ___ aparte.","resp":["cotiza","cobra","cotizar"],"pista":"Es lo que haces con un trabajo nuevo."},{"frase":"El alcance del proyecto se define ___ de empezar.","resp":["antes","previo"],"pista":"Lo contrario de después."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"El cliente pide una quinta ronda de cambios y tu propuesta decía tres. Lo mejor es…","ops":["Recordarle el alcance con amabilidad y cotizar las adicionales","Hacerlas gratis para no incomodarlo","Negarte a hacer más cambios sin explicarle por qué"],"correcta":0},{"p":"Una aprobación por WhatsApp del cliente…","ops":["Sirve como registro: guárdala","No vale para nada","Solo sirve si además la manda por correo"],"correcta":0},{"p":"Si el cliente tarda tres semanas en aprobar, la fecha de entrega…","ops":["Se recorre, y debía estar advertido en la propuesta","Se mantiene y tú te desvelas","Se cancela junto con el proyecto automáticamente"],"correcta":0}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso:</b> Gerardo hizo el video institucional de una constructora en Chihuahua. La propuesta incluía «un video de 2 minutos con 2 rondas de ajustes». Ya van cuatro rondas, ahora piden una versión vertical de 30 segundos para redes y cambiar la música «por una más alegre». El gerente escribe: «ya casi, nada más esto»."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"La versión vertical de 30 segundos es…","ops":["Un ajuste incluido","Un nuevo entregable que se cotiza aparte","Un favor obligatorio"],"correcta":1,"explica":"Otro formato y otra duración es otro entregable."},{"p":"¿Cómo responde a la ronda cinco?","ops":["Recuerda con amabilidad que el alcance incluía 2 rondas y cotiza las adicionales antes de hacerlas","La hace sin decir nada","Deja de contestar"],"correcta":0,"explica":"Recordar el alcance por escrito y cotizar evita perder la ganancia de a poquito."},{"p":"¿Qué le pide a la IA para ese mensaje?","ops":["Un mensaje que amenace con cobrar todo","Un mensaje que se disculpe por cobrar","Un mensaje breve, amable y firme que cite lo acordado y ofrezca opciones con precio"],"correcta":2,"explica":"Tono amable y firme, con el acuerdo y las opciones a la vista."}]},{"tipo":"relacionar","rotulo":"Petición del cliente y qué es","pares":[["Cambiar el tono de un texto dentro del video","Ajuste dentro de las rondas"],["Versión vertical de 30 segundos","Nuevo entregable, se cotiza"],["Rehacer el guion con otra idea","Cambio de concepto, se cotiza aparte"],["Ronda de ajustes número cinco","Ronda adicional, se cotiza"]]},{"tipo":"clave","items":["Entregables y rondas de ajustes, por escrito y desde el principio.","Cambio de concepto = cotización aparte.","Guarda cada aprobación, aunque sea un mensaje."]}],"c-ia-freelance-m3-l1":[{"tipo":"texto","texto":"Trabajar por tu cuenta no es tener todo el día libre: es tener todo el día ocupado por cosas que nadie más va a hacer. Cotizar, cobrar, prospectar, contestar y además producir. Si no apartas bloques, el trabajo del cliente que más grita se come la semana y los demás se enojan. La IA sirve para bajar tu lista a un plan realista y para redactar los avisos."},{"tipo":"plantilla","rotulo":"Tu semana en bloques","texto":"Estos son mis compromisos de la semana: [proyecto, entregable y fecha de cada uno]. Estas son mis horas disponibles reales: [días y horarios]. Tengo estas obligaciones fijas: [escuela de los hijos, otro empleo, etc.]. Arma un plan semanal por bloques de 2 horas que: 1) ponga el trabajo que exige concentración en mis mejores horas, 2) agrupe juntas y llamadas en un solo día, 3) deje un bloque para prospección y otro para cobranza, 4) deje un bloque vacío de respaldo. Dime también qué compromiso no cabe y debo renegociar."},{"tipo":"tabla","titulo":"Los cuatro bloques de la semana del independiente","encabezados":["Bloque","Qué va ahí","Cuándo conviene"],"filas":[["Producción","El trabajo por el que te pagan","Tus horas de mayor energía, sin celular"],["Contacto","Llamadas, juntas, mensajes de clientes","Agrupado en uno o dos días"],["Negocio","Prospección, propuestas, cobranza","Un bloque fijo semanal, no negociable"],["Respaldo","Lo que se atrasó y las urgencias","Al final de la semana, siempre vacío al planear"]]},{"tipo":"relacionar","rotulo":"Situación y qué bloque le toca","pares":[["Diseñar la carta del restaurante","Bloque de producción, sin interrupciones"],["Cinco clientes pidiendo estatus","Bloque de contacto, todos el mismo día"],["Nadie te ha escrito en dos semanas","Bloque de negocio: prospección"],["Se cayó el archivo el día de entrega","Bloque de respaldo: por eso está vacío"]]},{"tipo":"plantilla","rotulo":"Reporte de avance al cliente","texto":"Escribe un reporte de avance breve para enviar por WhatsApp o correo a [cliente], sobre [proyecto]: qué quedó listo esta semana, qué sigue, qué necesito de él y con qué fecha, y si hay algún riesgo para la entrega. Máximo 6 renglones, tono claro y tranquilo. Deja marcados con [ ] los datos que yo debo completar. No inventes avances que no te reporté."},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Mandar un avance corto cada semana, aunque no haya novedades grandes…","ops":["Evita que el cliente te persiga y da confianza","Es perder el tiempo","Solo sirve cuando hay avances grandes que mostrar"],"correcta":0},{"p":"El bloque de negocio (prospección y cobranza)…","ops":["Se agenda fijo aunque tengas mucho trabajo","Se hace cuando sobra tiempo","Se deja para el fin de semana"],"correcta":0},{"p":"Planear la semana al 100% de tus horas disponibles…","ops":["Garantiza que cualquier imprevisto te atrase","Es la forma más eficiente","Te asegura terminar antes de tiempo"],"correcta":0}]},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso:</b> Adriana es consultora de recursos humanos en Guadalajara y tiene tres clientes activos. Su lunes: 4 llamadas repartidas entre 9 am y 6 pm, un manual de inducción que entrega el jueves, dos cotizaciones pendientes y un cliente que le escribe a diario pidiendo estatus. Le pidió a la IA un plan y la IA acomodó 52 horas de trabajo en sus 40 horas disponibles."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué está mal en el plan de la IA?","ops":["Nada, se puede","Que usó bloques de 2 horas","Acomoda más horas de las que tiene y no deja bloque de respaldo"],"correcta":2,"explica":"Un plan imposible se rompe el martes. Algo se renegocia desde hoy."},{"p":"¿Qué hace con las 4 llamadas repartidas?","ops":["Las agrupa en un bloque de contacto, por ejemplo martes y jueves en la tarde","Las deja como están","Las cancela"],"correcta":0,"explica":"Las llamadas repartidas rompen los bloques de producción."},{"p":"¿Cómo atiende al cliente que pide estatus a diario?","ops":["Le contesta cada vez","Le manda un avance fijo cada viernes con qué está listo, qué sigue y qué necesita de él","Lo ignora"],"correcta":1,"explica":"Un avance semanal predecible reduce los mensajes de «¿cómo vamos?»."}]},{"tipo":"comparar","titulo":"La semana de Adriana","malTitulo":"Todo cabe","mal":"52 horas acomodadas en 40, llamadas en medio de cada mañana, sin bloque de respaldo ni de negocio.","bienTitulo":"Lo que sí cabe","bien":"Producción del manual en las mañanas, llamadas agrupadas martes y jueves en la tarde, bloque de negocio el miércoles, respaldo el viernes vacío, y 12 horas renegociadas desde el lunes con el cliente menos urgente."},{"tipo":"clave","items":["Producción, contacto, negocio y respaldo: cuatro bloques.","El bloque de respaldo se planea vacío a propósito.","Un avance semanal corto vale más que diez disculpas."]}],"c-ia-freelance-m3-l2":[{"tipo":"texto","texto":"Cobrar no es pedir un favor: es la última parte de tu trabajo. Lo que hace incómoda la cobranza es la improvisación. Si la fecha de pago quedó por escrito y mandas un recordatorio antes del vencimiento, casi nunca llegas al mensaje difícil. Y si llegas, lo haces con datos: número de cotización, fecha acordada y entregables recibidos."},{"tipo":"plantilla","rotulo":"Tus cuatro recordatorios de pago","texto":"Escribe cuatro mensajes breves para cobrar a un cliente, con [NOMBRE], [MONTO], [FOLIO] y [FECHA] como campos: 1) tres días antes del vencimiento, cordial; 2) el día del vencimiento, informativo; 3) a los siete días, firme y con los datos del acuerdo; 4) a los quince días, firme, con la consecuencia acordada (pausa de trabajos) y ofreciendo un plan de pago. Máximo 4 renglones cada uno, español de México, sin sonar agresivo ni suplicante."},{"tipo":"excel","rotulo":"¿Cuánto te dejó cada proyecto?","datos":[["Proyecto","Cobrado","Horas reales"],["Tienda en línea",30200,72],["Manual de marca",15000,20],["Campaña de anuncios",9000,34],["Peor tarifa real por hora","",""]],"retos":[{"celda":"D2","formula":"=B2/C2","esperado":419.4444444444444,"texto":"<b>D2</b>: pesos por hora reales de la tienda en línea."},{"celda":"D3","formula":"=B3/C3","esperado":750,"texto":"<b>D3</b>: pesos por hora del manual de marca."},{"celda":"D4","formula":"=B4/C4","esperado":264.70588235294116,"texto":"<b>D4</b>: pesos por hora de la campaña de anuncios."},{"celda":"D5","formula":"=MIN(D2:D4)","esperado":264.70588235294116,"requiere":"MIN(","texto":"<b>D5</b>: la peor tarifa real por hora de los tres.","explica":"La campaña te dejó unos $265 por hora cuando tu tarifa es de $600: ese proyecto se llevó el doble de horas de las que cotizaste. No siempre hay que dejar de tomarlos, pero sí hay que volver a cotizarlos con las horas reales."}]},{"tipo":"practica","rotulo":"Comprueba","preguntas":[{"p":"Un proyecto que te deja menos por hora que tu tarifa…","ops":["Se vuelve a cotizar con las horas reales","Se toma igual, algo es algo","Se compensa subiéndole la tarifa a otro cliente sin avisar"],"correcta":0},{"p":"El primer recordatorio de pago conviene enviarlo…","ops":["Antes de la fecha de vencimiento","Un mes después del vencimiento","Solo cuando ya pasaron 15 días de atraso"],"correcta":0},{"p":"Para saber si un cliente te conviene necesitas registrar…","ops":["Tus horas reales trabajadas","Solo lo que te pagó","Cuántos mensajes te manda al día"],"correcta":0}]},{"tipo":"destacado","texto":"<b>Cuándo parar el trabajo.</b> Si acordaste por escrito que los trabajos se pausan con pagos vencidos, cúmplelo: avisa con claridad, sin enojo y con la puerta abierta a un plan de pago. Lo que no se vale es pausar sin avisar. Y antes de amenazar con cualquier acción legal, consulta a un abogado: no uses lo que te diga la IA como si fuera asesoría jurídica."},{"tipo":"reflexion","rotulo":"Tu cliente más caro","pregunta":"Piensa en el proyecto que más horas te comió el año pasado. ¿Cuánto cobraste, cuántas horas le metiste de verdad y qué harías distinto al cotizarlo hoy?","ayuda":"Cobré… / Horas reales… / Hoy lo cotizaría…"},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso:</b> Iván diseña empaques en Puebla. Un cliente le debe $22,000 desde hace 25 días. Iván le pidió a la IA un mensaje «para que ya pague» y la IA escribió: «Si no paga hoy, procederé legalmente y lo reportaré a buró de crédito». En su cotización no se acordó ninguna consecuencia por atraso."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Por qué no manda ese mensaje?","ops":["Porque es muy largo","Amenaza con acciones que no acordó ni consultó con un abogado y rompe la relación de golpe","Porque no tiene saludo"],"correcta":1,"explica":"Antes de hablar de acciones legales se consulta a un abogado. La IA no es asesoría jurídica."},{"p":"¿Qué mensaje conviene a los 25 días?","ops":["Firme y con datos: folio, monto, fecha acordada, entregables recibidos y una propuesta de plan de pago","Uno que pida perdón por cobrar","Ninguno, esperar"],"correcta":0,"explica":"Firmeza con datos y una salida concreta."},{"p":"¿Qué cambia Iván en sus próximas cotizaciones?","ops":["Nada","Cobrar el doble","Fecha de pago, recordatorio previo y pausa de trabajos acordada por escrito"],"correcta":2,"explica":"La cobranza se planea desde la cotización."}]},{"tipo":"comparar","titulo":"El mensaje de cobranza","malTitulo":"Amenaza improvisada","mal":"«Si no paga hoy, procederé legalmente y lo reportaré a buró de crédito.»","bienTitulo":"Firme y con datos","bien":"«Hola, Luis. Te escribo por la cotización F-118 por $22,000, con pago acordado el 5 de marzo; los archivos se entregaron el 1 de marzo. ¿Podemos cerrar el pago esta semana o prefieres dividirlo en dos pagos, el 20 y el 30?»"},{"tipo":"reflexion","rotulo":"Tu cobranza pendiente","pregunta":"Si hoy tienes un pago atrasado, escribe el mensaje con folio, monto, fecha acordada, entregables y una propuesta de plan. Si no tienes, escribe la cláusula de pago que agregarás a tu siguiente cotización.","ayuda":"Hola… folio… monto… fecha… Te propongo… / Cláusula: El pago…"},{"tipo":"clave","items":["La cobranza se planea desde la cotización.","Registra tus horas reales: ahí se ve el cliente que no conviene.","Pausar trabajos solo si estaba acordado, y avisando."]}],"c-ia-freelance-m3-l3":[{"tipo":"destacado","texto":"<b>El caso:</b> te escribe por WhatsApp la dueña de una cafetería en Puebla. Quiere «todo lo de redes y una página». No tiene presupuesto definido, quiere verlo «para la próxima semana» y ya trabajó con alguien que la dejó plantada. Tú cobras $600 la hora y calculas unas 45 horas de trabajo más $3,200 de gastos directos."},{"tipo":"pasos","rotulo":"Resuélvelo con la IA","pasos":["<b>Oferta (M1 L1):</b> contesta con tu frase de presentación específica y una pregunta que aterrice qué necesita de verdad.","<b>Tarifa (M1 L2):</b> confirma tu tarifa por hora en la hoja antes de dar cualquier número.","<b>Propuesta (M2 L1):</b> una página, con entregables contables, tiempos y sección de qué no incluye.","<b>Cotización (M2 L2):</b> horas × tarifa + gastos, anticipo del 50% y vigencia.","<b>Alcance (M2 L3):</b> tres rondas de ajustes y cambios de concepto cotizados aparte.","<b>Semana (M3 L1):</b> mete la producción en bloques y manda avance cada viernes.","<b>Cobranza (M3 L2):</b> recordatorio tres días antes del saldo y archivos finales contra pago."]},{"tipo":"practica","rotulo":"Decisiones del caso","preguntas":[{"p":"La clienta pide «un estimado rápido» por WhatsApp antes de que definan nada. Tú…","ops":["Le das un rango con la condición de aterrizar el alcance y mandas propuesta","Le tiras un número para no perderla","Le dices que no das ningún precio sin contrato firmado"],"correcta":0},{"p":"Quiere todo «para la próxima semana» y tú calculaste 45 horas. Lo correcto es…","ops":["Proponer una primera entrega parcial con fecha realista","Aceptar y desvelarte","Rechazar el proyecto de inmediato"],"correcta":0},{"p":"Como ya la dejaron plantada antes, ella pide no pagar anticipo. Tú…","ops":["Ofreces un anticipo menor con entregas parciales, pero no arrancas sin pago","Trabajas gratis para ganarte su confianza","Empiezas sin anticipo y le cobras todo al final"],"correcta":0},{"p":"A media obra pide agregar una tienda en línea. Eso es…","ops":["Cambio de concepto: se cotiza aparte","Un ajuste incluido","Un error tuyo por no haberlo previsto, así que va sin costo"],"correcta":0}]},{"tipo":"reflexion","rotulo":"Tu próximo cliente","pregunta":"Escribe los tres documentos que vas a tener listos antes de tu siguiente cotización: tu cálculo de tarifa, tu plantilla de propuesta y tu texto de recordatorio de pago. ¿Cuál te falta hoy?","ayuda":"Ya tengo… / Me falta… / Lo armo el día…"},{"tipo":"destacado","texto":"<b>¡Terminaste el curso!</b> La IA te ayuda a redactar, ordenar y dar seguimiento; los números salen de tu hoja de cálculo y los acuerdos, de lo que escribes con el cliente antes de empezar. Ese es el negocio."},{"tipo":"titulo","texto":"Taller práctico"},{"tipo":"destacado","texto":"<b>Caso:</b> Seis semanas después, la cafetería de Puebla ya tiene su página y sus redes. La dueña quiere seguir con «las redes cada mes» y pregunta cuánto sería. Tus horas reales del proyecto fueron 58, no 45, y tu tarifa sigue en $600."},{"tipo":"practica","rotulo":"Decide en el caso","preguntas":[{"p":"¿Qué aprendes de las 58 horas reales?","ops":["Que la próxima cotización de un proyecto parecido usa tus horas reales","Nada, ya se cobró","Que debes cobrarle la diferencia ahora"],"correcta":0,"explica":"La diferencia se aprende, no se cobra retroactivamente si no se acordó."},{"p":"¿Cómo cotizas la iguala mensual?","ops":["Un monto fijo sin decir qué incluye","Con entregables contables al mes, horas estimadas, límite de cambios y qué se cobra aparte","Por hora sin tope"],"correcta":1,"explica":"Una iguala sin límite se vuelve disponibilidad total."},{"p":"¿Qué pides antes de publicar el caso en tu portafolio?","ops":["Nada","Que te pague más","Permiso de la dueña para usar su nombre y su trabajo"],"correcta":2,"explica":"El permiso protege la relación y tu reputación."}]},{"tipo":"completar","rotulo":"Completa la lección","instruccion":"Escribe la palabra que falta.","items":[{"frase":"La próxima vez cotizas con tus horas ___, no con las que estimaste.","resp":["reales"],"pista":"Las que registraste."},{"frase":"Una iguala dice qué ___ al mes y qué se cobra aparte.","resp":["incluye","entregas","entrego"],"pista":"El alcance mensual."},{"frase":"Antes de publicar el caso en tu portafolio pides ___.","resp":["permiso","autorización","autorizacion"],"pista":"Al cliente."}]},{"tipo":"clave","titulo":"Tu kit de independiente con IA","items":["Oferta específica, tarifa con sustento y prospección semanal.","Propuesta de una página, cotización con anticipo y alcance por escrito.","Semana en bloques, avances semanales, cobranza planeada y horas reales registradas."]}],"c-ia-freelance-m4-l1":[{"tipo":"texto","texto":"Muchos independientes trabajan solo con la propuesta y un «va, empieza». Funciona hasta que algo sale mal. Un contrato de servicios sencillo deja claro el alcance, los pagos, qué pasa si alguien cancela y <b>de quién son los derechos del trabajo</b>. La IA es útil para armar el borrador y para explicarte en palabras simples lo que dice un contrato que te mandan. No sustituye al abogado: la revisión final, sobre todo en proyectos grandes, la hace un profesional."},{"tipo":"tabla","titulo":"Cláusulas que conviene revisar con lupa","encabezados":["Cláusula","Qué cuidar","Error común de la IA"],"filas":[["Alcance y entregables","Que coincida con tu propuesta","Lo describe en términos generales que no se pueden medir"],["Pagos","Montos, fechas, anticipo y qué pasa con el atraso","Pone plazos o penalizaciones que no acordaste"],["Cancelación","Qué se paga si el cliente cancela a medias","La omite o la deja solo a favor de una parte"],["Derechos del trabajo","Cuándo pasan al cliente y para qué usos","Cede todos los derechos desde la firma, antes de que te paguen"],["Confidencialidad","Qué información es confidencial y por cuánto tiempo","Te prohíbe mostrar el trabajo en tu portafolio sin que lo notes"],["Ley y tribunales","Qué leyes y qué ciudad aplican","Cita leyes de otro país o artículos que no existen"]],"nota":"Esto no es asesoría legal. Las reglas de contratos y de derechos de autor tienen matices; consulta a un abogado para tu caso."},{"tipo":"plantilla","rotulo":"Borrador de contrato para revisar con abogado","texto":"Arma el borrador de un contrato de prestación de servicios profesionales en México entre [yo, profesión] y [tipo de cliente, sin nombre real]. Datos: entregables [lista contable], rondas de ajustes [número], honorarios [monto], anticipo [%] y saldo [cuándo], vigencia [fechas], qué pasa si el cliente cancela [lo que propongo], los derechos del trabajo pasan al cliente [cuándo: al recibir el pago total] para [usos], puedo mostrar el trabajo en mi portafolio [sí/no, con qué condición]. Lenguaje claro. No cites artículos de ley específicos. Al final lista los puntos que debo revisar con un abogado."},{"tipo":"destacado","texto":"<b>Lo que el cliente te confía no va al chat.</b> Si firmaste un acuerdo de confidencialidad, o simplemente el cliente te compartió sus ventas, su lista de clientes o su estrategia, eso no se pega en una herramienta de IA pública. Sustituye nombres y cifras por marcadores como [CLIENTE] o [VENTAS DEL MES], o trabaja con una herramienta que tu cliente haya aprobado."},{"tipo":"practica","rotulo":"Decide","preguntas":[{"p":"El contrato que te mandó el cliente dice que los derechos pasan a él «desde la firma». ¿Qué propones?","ops":["Que pasen al recibir el pago total","Nada, es normal","Que nunca pasen"],"correcta":0,"explica":"Si los derechos se ceden antes del pago, pierdes tu principal respaldo si no te pagan. Revísalo con un abogado."},{"p":"La IA cita «el artículo 34 de la ley de servicios freelance». ¿Qué haces?","ops":["Lo dejas, suena formal","Lo quitas y verificas en fuente oficial o con un abogado cualquier referencia legal","Le cambias el número"],"correcta":1,"explica":"La IA puede inventar leyes y artículos. Toda referencia legal se verifica."},{"p":"Quieres que la IA mejore la estrategia de ventas de tu cliente, que tiene confidencialidad firmada. Le pegas…","ops":["El documento completo con sus cifras","Solo las cifras","Una versión con marcadores en lugar de nombres, clientes y cifras reales"],"correcta":2,"explica":"La información confidencial no sale de tu control; los marcadores permiten trabajar igual."}]},{"tipo":"reflexion","rotulo":"Tu contrato","pregunta":"Revisa el último contrato o acuerdo que firmaste (o el que usarás). Escribe qué dice sobre pagos, cancelación, derechos del trabajo y portafolio, y qué le preguntarías a un abogado.","ayuda":"Pagos… Cancelación… Derechos… Portafolio… Le preguntaría al abogado…"},{"tipo":"clave","items":["La IA arma el borrador; un abogado revisa lo importante.","Derechos del trabajo al recibir el pago total, por escrito.","La información confidencial del cliente no se pega en la IA."]}],"c-ia-freelance-m4-l2":[{"tipo":"texto","texto":"El independiente no tiene quincena: un mes cobra $60,000 y el siguiente $9,000. El error típico es gastar al ritmo del mes bueno. La solución es separar desde que entra cada pago: <b>una parte para impuestos, una para tu colchón y lo demás para tu sueldo</b>. Cuánto apartar para impuestos depende de tu régimen fiscal y de tus deducciones. Hay personas físicas que tributan en regímenes como el RESICO o el de actividades empresariales y profesionales, entre otros: cuál te conviene, qué tasas aplican y qué puedes deducir cambia con tu situación y con las reglas vigentes, así que <b>verifica con tu contador</b>. No se lo preguntes a la IA."},{"tipo":"excel","rotulo":"Tu flujo de un trimestre","datos":[["Mes","Cobrado","Gastos del mes"],["Julio",58000,31000],["Agosto",12000,31000],["Septiembre",34000,31000],["Total del trimestre",104000,93000],["Apartado para impuestos (porcentaje de ejemplo, defínelo con tu contador)",0.12,""],["Disponible después del apartado","",""],["Resultado del trimestre","",""]],"retos":[{"celda":"B7","formula":"=B5*(1-B6)","esperado":91520,"texto":"<b>B7</b>: lo que queda después de apartar el porcentaje de impuestos."},{"celda":"B8","formula":"=B7-C5","esperado":-1480,"texto":"<b>B8</b>: disponible menos gastos del trimestre.","explica":"Aunque julio se vio excelente, después del apartado el trimestre quedó $1,480 abajo. Si en julio hubieras gastado al ritmo de ese mes, agosto habría dolido todavía más. El 12% es solo un ejemplo: tu porcentaje real lo defines con tu contador."}]},{"tipo":"excel","rotulo":"¿Cuántos meses aguantas sin clientes?","datos":[["Concepto","Pesos"],["Ahorro disponible hoy",45000],["Gastos fijos del mes (personales y del trabajo)",31000],["Meses de colchón",""],["Meta: meses de colchón que quieres",3],["Te falta ahorrar",""]],"retos":[{"celda":"B4","formula":"=REDONDEAR(B2/B3,1)","esperado":1.5,"requiere":"REDONDEAR(","texto":"<b>B4</b>: meses de colchón = ahorro ÷ gastos fijos, con 1 decimal."},{"celda":"B6","formula":"=MAX(B5*B3-B2,0)","esperado":48000,"requiere":"MAX(","texto":"<b>B6</b>: cuánto te falta para la meta (si ya la cumpliste, 0).","explica":"Te faltan $48,000 para aguantar tres meses sin ingresos. Con un colchón así, puedes decir que no a un proyecto que no conviene sin entrar en pánico."}]},{"tipo":"tabla","titulo":"Errores comunes de la IA en dinero e impuestos del independiente","encabezados":["La IA…","Tú…"],"filas":[["Afirma qué régimen te conviene o qué tasa pagas","Lo consultas con tu contador con tus datos reales"],["Dice que algo «es deducible» sin conocer tu régimen","Preguntas a tu contador antes de contar con esa deducción"],["Da fechas de declaraciones o límites de ingresos","Verificas las vigentes con tu contador o en el portal del SAT"],["Calcula tus impuestos a partir de tu descripción","Usas la hoja para planear el apartado; el cálculo lo hace tu contador"]]},{"tipo":"practica","rotulo":"Decide","preguntas":[{"p":"La IA te dice «como ganas menos de cierto monto, te conviene el RESICO». Tú…","ops":["Te cambias de régimen","Lo tomas como una pregunta para tu contador, con tus ingresos y gastos reales","Lo compartes en redes"],"correcta":1,"explica":"El régimen conveniente depende de tu situación y de las reglas vigentes: verifica con tu contador."},{"p":"Julio fue tu mejor mes. Lo más sano es…","ops":["Gastar al ritmo de julio","Tomarte vacaciones con todo","Apartar impuestos y colchón, y pagarte un sueldo fijo del resto"],"correcta":2,"explica":"El sueldo fijo te protege de los meses flojos."},{"p":"Tienes 1.5 meses de colchón y un cliente te ofrece un proyecto que te deja $250 por hora. Tu tarifa es $600. Te ayuda…","ops":["Saber tu colchón y tu meta, para decidir con números y no con miedo","Aceptar cualquier cosa","Pedirle a la IA que decida"],"correcta":0,"explica":"El colchón te da margen para decidir; la decisión es tuya."}]},{"tipo":"reflexion","rotulo":"Tu reparto","pregunta":"Escribe cómo vas a repartir cada pago que entre: qué porcentaje para impuestos (según lo que te diga tu contador), cuánto para tu colchón, cuánto es tu sueldo fijo y las preguntas que le llevarás a tu contador.","ayuda":"Impuestos: …% (confirmar con mi contador) / Colchón: … / Sueldo fijo: $… / Preguntas: 1) … 2) …"},{"tipo":"clave","items":["Separa impuestos, colchón y sueldo desde que entra cada pago.","RESICO, actividad empresarial u otro régimen: verifica con tu contador.","Tu colchón en meses te permite decir que no con números."]}],"c-ia-freelance-m4-l3":[{"tipo":"texto","texto":"Dos conversaciones que casi todo independiente pospone: <b>avisar que sube tu tarifa</b> y <b>decir que no</b>. Las dos se vuelven más fáciles con números (tu tarifa real, tu colchón, lo que te dejó cada cliente) y con un mensaje preparado con calma. La IA redacta bien este tipo de mensajes si le das el contexto; lo que no debe hacer es inventar razones ni exagerar."},{"tipo":"tabla","titulo":"Cuándo subir tarifa y cuándo decir que no","encabezados":["Señal","Qué haces"],"filas":[["Tu agenda está llena varios meses seguidos","Subes la tarifa a clientes nuevos y avisas con anticipación a los actuales"],["Un cliente te deja muy por debajo de tu tarifa real","Le propones nuevo precio o menos alcance; si no, cierras la relación con cuidado"],["El proyecto no es de tu especialidad","Lo rechazas o recomiendas a alguien de confianza"],["El cliente no acepta anticipo ni alcance por escrito","Dices que no: el riesgo es todo tuyo"],["Tus gastos subieron desde tu último cálculo","Recalculas en la hoja y ajustas"]]},{"tipo":"plantilla","rotulo":"Aviso de aumento de tarifa","texto":"Escribe un mensaje para avisar a [tipo de cliente, con cuánto tiempo trabajando juntos] que mi tarifa pasa de [monto actual] a [monto nuevo] a partir de [fecha, con al menos 30 días de anticipación]. Contexto real: [por qué: gastos, más especialización, agenda llena]. El mensaje debe: agradecer la relación sin exagerar, dar el nuevo monto y la fecha, decir qué se mantiene igual, ofrecer una alternativa si el presupuesto no alcanza (menos entregables o frecuencia) y cerrar con disposición a platicarlo. Máximo 8 renglones, español de México, sin disculparse de más ni inventar razones."},{"tipo":"comparar","titulo":"Decir que no","malTitulo":"Excusa","mal":"«Uy, qué pena, ahorita ando súper saturado, a ver si más adelante…» — y el cliente vuelve a escribir en dos semanas.","bienTitulo":"Claro y útil","bien":"«Gracias por pensar en mí. Este proyecto no es mi especialidad y no te daría el resultado que buscas. Te recomiendo a Carla, que hace justo eso. Si más adelante necesitas [lo que sí haces], con gusto platicamos.»"},{"tipo":"practica","rotulo":"Decide","preguntas":[{"p":"La IA agregó al aviso de aumento «debido a la inflación del 20%». Tú no diste esa cifra. Tú…","ops":["La dejas, suena convincente","La cambias por 10%","La quitas y explicas solo tus razones reales"],"correcta":2,"explica":"Una cifra inventada daña tu credibilidad si el cliente la revisa."},{"p":"Tu cliente más antiguo paga $400 la hora y tu tarifa real es $600. ¿Qué conviene?","ops":["Avisar con anticipación del nuevo precio y ofrecer menos alcance si no le alcanza","Subirle sin avisar en la siguiente factura","Seguir igual para siempre"],"correcta":0,"explica":"Anticipación y alternativa cuidan la relación y tu ganancia."},{"p":"Te piden un proyecto que no es tu especialidad. Lo más profesional es…","ops":["Aceptarlo y aprender sobre la marcha sin decir nada","Decir que no con claridad y, si puedes, recomendar a alguien de confianza","No contestar"],"correcta":1,"explica":"Un no claro con recomendación deja la puerta abierta para lo que sí haces."}]},{"tipo":"reflexion","rotulo":"Tu aviso","pregunta":"Recalcula tu tarifa con tus gastos actuales. Escribe a qué cliente le avisarías primero del nuevo precio, con qué fecha y qué alternativa le ofrecerías.","ayuda":"Mi tarifa real hoy: $… / Cliente… / Fecha de aviso… / Nueva tarifa desde… / Alternativa…"},{"tipo":"clave","items":["Subir tarifa: con números, anticipación y una alternativa.","Decir que no con claridad es más profesional que una excusa.","La IA redacta; las razones y las cifras son tuyas y reales."]}],"c-ia-freelance-m5-l1":[{"tipo":"texto","texto":"Fernanda es consultora de mercadotecnia independiente en Aguascalientes. Hoy usa un asistente de IA en cuatro momentos del día. En cada escena hay al menos un error plantado. Tu trabajo: encontrarlo antes de enviar, firmar o cobrar."},{"tipo":"destacado","texto":"<b>Escena 1 · 9:00 am — La propuesta.</b> Para una propuesta a una cadena de gimnasios, Fernanda pegó en la IA el reporte de ventas y la base de clientes de su cliente anterior, una tienda deportiva con la que firmó confidencialidad, «para que tome ideas». La propuesta generada dice: «Con nuestra metodología, la tienda deportiva aumentó 180% sus ventas en tres meses». Fernanda nunca midió eso."},{"tipo":"reflexion","rotulo":"Escena 1: ¿qué encontraste?","pregunta":"Enumera los dos errores de la escena, qué debe hacer Fernanda con lo que ya pegó y cómo reescribiría el caso de éxito con datos reales.","ayuda":"Error 1… Error 2… Lo que ya pegó… Caso de éxito corregido: …"},{"tipo":"destacado","texto":"<b>Escena 2 · 12:00 pm — La cotización.</b> Fernanda le dio a la IA: 40 horas a $650 y $4,500 de gastos directos, anticipo del 50%. La IA escribió: «Honorarios $26,000. Total $26,000. Anticipo $13,000. Nota: como persona física en RESICO no debes cobrar IVA». Fernanda no le dijo su régimen."},{"tipo":"reflexion","rotulo":"Escena 2: ¿qué encontraste?","pregunta":"Calcula el total y el anticipo correctos y explica qué hace Fernanda con la nota sobre el IVA.","ayuda":"Total = 26,000 + 4,500 = … Anticipo = … La nota fiscal… verifica con tu contador…"},{"tipo":"destacado","texto":"<b>Escena 3 · 3:00 pm — El contrato.</b> La IA armó el contrato. Dice: «El cliente adquiere todos los derechos del material desde la firma de este contrato», «El prestador no podrá mostrar el trabajo en ningún medio» y «En caso de cancelación, el cliente no pagará los trabajos realizados». Fernanda quería mostrar el trabajo en su portafolio."},{"tipo":"reflexion","rotulo":"Escena 3: ¿qué encontraste?","pregunta":"Reescribe las tres cláusulas como a Fernanda le convienen y escribe qué le preguntaría a un abogado antes de firmar.","ayuda":"Derechos: … Portafolio: … Cancelación: … Preguntas al abogado: …"},{"tipo":"destacado","texto":"<b>Escena 4 · 6:00 pm — La cobranza.</b> Un cliente tiene 10 días de atraso en el saldo. La IA redactó: «Última advertencia. Si no pagas mañana, publicaré en redes que eres un mal cliente y te demandaré». Además, Fernanda ya le había entregado los archivos finales."},{"tipo":"reflexion","rotulo":"Escena 4: ¿qué encontraste?","pregunta":"Reescribe el mensaje de cobranza con datos y una salida, y anota qué cambiará en su proceso para no entregar archivos finales antes del saldo.","ayuda":"Hola… folio… monto… fecha acordada… Te propongo… / En mi proceso cambio…"},{"tipo":"practica","rotulo":"Revisión del día","preguntas":[{"p":"Escena 1: ¿qué hace Fernanda con la información de la tienda que pegó?","ops":["Nada, ya está hecho","Revisa las condiciones de la herramienta y de su acuerdo de confidencialidad, y valora avisar a su cliente según lo acordado","La vuelve a pegar en otro chat"],"correcta":1,"explica":"Violar una confidencialidad es serio; se atiende con lo que diga el acuerdo, y si hay duda, con un abogado."},{"p":"Escena 2: el total correcto de la cotización es…","ops":["$30,500","$26,000","$13,000"],"correcta":0,"explica":"Honorarios $26,000 + gastos $4,500 = $30,500; el anticipo del 50% es $15,250."},{"p":"Escena 2: la nota sobre RESICO e IVA…","ops":["Se deja, suena técnica","Se cambia por otra tasa","Se quita y se verifica con su contador"],"correcta":2,"explica":"La IA no conoce su régimen ni su situación; lo fiscal se verifica con su contador."},{"p":"Escena 3: la cláusula de derechos debe decir que pasan al cliente…","ops":["Desde la firma","Al recibir el pago total, y con permiso para mostrar el trabajo en su portafolio si así lo acuerdan","Nunca"],"correcta":1,"explica":"Así conserva su respaldo si no le pagan y protege su portafolio."},{"p":"Escena 4: amenazar con exhibir al cliente en redes…","ops":["Presiona y funciona","Es aceptable si ya pasó un mes","Daña la relación y puede traerle problemas; se cobra con datos y, si hace falta, se consulta a un abogado"],"correcta":2,"explica":"Firmeza con datos y asesoría profesional, no amenazas improvisadas."}]},{"tipo":"clave","items":["Nada confidencial de un cliente va a la IA, y nada inventado va a la propuesta.","Las cuentas salen de tu hoja; lo fiscal, de tu contador.","Contratos con derechos contra pago y cobranza con datos, no con amenazas."]}],"c-ia-freelance-m5-l2":[{"tipo":"texto","texto":"Cierra el curso armando tu <b>kit de independiente con IA</b>: lo que vas a usar con cada cliente, del primer mensaje al último pago. Trabaja con tu negocio real. Guárdalo en un solo documento con fecha y revísalo cada trimestre, cuando actualices tu tarifa."},{"tipo":"reflexion","rotulo":"Paso 1 · Tu biblioteca de prompts","pregunta":"Elige las 7 plantillas del curso que más usarás (oferta, sustentar precio, primer contacto, propuesta, cotización, alcance, semana, avance, recordatorios de pago, contrato, aviso de tarifa) y adapta cada una con tus datos fijos: especialidad, tipo de cliente, tarifa, anticipo, rondas de ajustes y tono.","ayuda":"1. Propuesta: Soy [mi especialidad] y trabajo con [mi tipo de cliente]… 2. …"},{"tipo":"reflexion","rotulo":"Paso 2 · Tu política de datos de clientes","pregunta":"Escribe 5 reglas sobre qué información de tus clientes nunca pegas en la IA (confidencialidad, cifras, bases de clientes, contraseñas de sus cuentas), cómo la sustituyes y qué haces si algo se filtra.","ayuda":"Nunca pego… La sustituyo con… Si algo se filtra…"},{"tipo":"reflexion","rotulo":"Paso 3 · Tu lista de verificación","pregunta":"Arma tu lista de 8 puntos para revisar todo lo que la IA te prepare antes de enviarlo: cifras y logros reales, montos calculados en tu hoja, entregables contables, qué no incluye, vigencia, cláusulas de derechos y cancelación, nada fiscal sin tu contador y tono de cobranza.","ayuda":"Antes de enviar reviso: 1) … 2) … 3) …"},{"tipo":"reflexion","rotulo":"Paso 4 · Tu entregable real","pregunta":"Prepara con tu kit una propuesta y cotización reales para un cliente actual o próximo, pásala por tu lista y anota qué corregiste de lo que propuso la IA.","ayuda":"Cliente… La IA propuso… Corregí… Total… Anticipo… Vigencia…"},{"tipo":"plantilla","rotulo":"Índice de tu kit","texto":"KIT DE INDEPENDIENTE CON IA — [nombre] — versión [fecha]\n\n1. Datos fijos (especialidad, cliente ideal, frase de presentación, tarifa, anticipo, rondas)\n2. Biblioteca de prompts\n   2.1 Primer contacto · 2.2 Propuesta · 2.3 Cotización · 2.4 Alcance y cambios\n   2.5 Avance semanal · 2.6 Recordatorios de pago · 2.7 Contrato · 2.8 Aviso de tarifa\n3. Política de datos de clientes (5 reglas)\n4. Lista de verificación antes de enviar (8 puntos)\n5. Hojas: tarifa, cotización, rentabilidad por proyecto, flujo y colchón\n6. Preguntas pendientes para mi contador: [ ]\n7. Puntos para revisar con un abogado: [ ]\n8. Entregable real revisado: [ ]\n9. Próxima revisión del kit y de mi tarifa: [fecha]","nota":"Cópiala y adáptala."},{"tipo":"destacado","texto":"<b>¡Terminaste el curso completo!</b> La IA te ahorra horas de redacción; tu kit te protege de cobrar mal, prometer de más y exponer a tus clientes. Las cifras salen de tu hoja, lo fiscal de tu contador, lo legal de tu abogado, y la responsabilidad frente a tu cliente es tuya."},{"tipo":"clave","items":["Biblioteca de prompts con tus datos fijos.","Política de datos de clientes y lista de verificación antes de enviar.","Una propuesta real revisada y fecha para actualizar tu tarifa."]}]},"q":{"c-ia-freelance-m1":[{"p":"Una oferta específica sirve para…","ops":["Que te recuerden y te recomienden","Que te contraten para todo","Cobrar menos","Nada"],"correcta":0},{"p":"Si la IA inventa un logro tuyo…","ops":["Lo corriges con tu dato real","Lo publicas","Lo redondeas","Lo escondes"],"correcta":0},{"p":"Tarifa por hora =","ops":["(Gastos + lo que necesitas ganar) ÷ horas facturables","Gastos × horas","Lo que cobra el vecino","Ingresos ÷ gastos"],"correcta":0},{"p":"Las horas facturables son…","ops":["Las que de verdad le cobras a un cliente","Todas las del mes","Solo las de junta","Las de descanso"],"correcta":0},{"p":"El riesgo de cobrar por proyecto es…","ops":["Que el alcance crezca y tú pagues la diferencia","Que el cliente pague de más","Ninguno","Que no puedas facturar"],"correcta":0},{"p":"Una iguala mensual siempre debe decir…","ops":["Qué incluye y qué no","Solo el monto","La fecha de pago nada más","Nada"],"correcta":0},{"p":"La prospección conviene hacerla…","ops":["En un bloque fijo cada semana","Solo cuando no hay trabajo","Una vez al año","Nunca"],"correcta":0},{"p":"Antes de publicar el trabajo de un cliente…","ops":["Le pides permiso","Lo publicas y luego avisas","No se publica nunca","Lo borras"],"correcta":0}],"c-ia-freelance-m2":[{"p":"Un entregable útil es…","ops":["Contable: «12 publicaciones al mes»","«Mejorar sus redes»","«Apoyo general»","«Lo que se ofrezca»"],"correcta":0},{"p":"La sección «no incluye» de la propuesta…","ops":["Evita el conflicto posterior","Sobra","Ahuyenta clientes","Es ilegal"],"correcta":0},{"p":"Total del proyecto =","ops":["Horas × tarifa + gastos directos","Horas ÷ tarifa","Tarifa − gastos","Gastos × 2"],"correcta":0},{"p":"El anticipo sirve para…","ops":["Pagar tus primeras semanas y filtrar clientes serios","Desconfiar del cliente","Subir el precio","Nada"],"correcta":0},{"p":"Los archivos finales se entregan…","ops":["Contra el pago del saldo","Antes de cobrar","Cuando el cliente insiste","Nunca"],"correcta":0},{"p":"Las dudas de facturación e impuestos se consultan con…","ops":["Tu contador","La IA","Otro freelancer","Nadie"],"correcta":0},{"p":"Un cambio de concepto a media obra…","ops":["Se cotiza aparte","Se hace gratis","Se ignora","Termina el proyecto"],"correcta":0},{"p":"La vigencia en una propuesta sirve para…","ops":["Que el precio no quede abierto para siempre","Presionar de más","Nada","Subir el precio"],"correcta":0}],"c-ia-freelance-m3":[{"p":"El bloque de respaldo de tu semana se planea…","ops":["Vacío, para imprevistos","Lleno de trabajo","Solo en diciembre","Nunca"],"correcta":0},{"p":"Un reporte de avance semanal sirve para…","ops":["Que el cliente no tenga que perseguirte","Alargar el proyecto","Subir el precio","Nada"],"correcta":0},{"p":"La cobranza se planea…","ops":["Desde la cotización","Cuando ya hay atraso","Con un abogado desde el día uno","Nunca"],"correcta":0},{"p":"Pesos por hora reales de un proyecto =","ops":["Cobrado ÷ horas reales","Horas ÷ cobrado","Cobrado × horas","Tarifa ÷ 2"],"correcta":0},{"p":"Si un proyecto te deja menos por hora que tu tarifa…","ops":["Lo vuelves a cotizar con horas reales","Lo repites igual","Subes las horas al cliente sin avisar","Nada"],"correcta":0},{"p":"Antes de amenazar con acciones legales por falta de pago…","ops":["Consultas a un abogado","Le preguntas a la IA","Publicas al cliente en redes","Nada"],"correcta":0},{"p":"Pausar los trabajos por pagos vencidos es válido si…","ops":["Estaba acordado por escrito y avisas","Nunca","Sin avisar está bien","Lo decide la IA"],"correcta":0},{"p":"Para un freelancer, la IA sirve sobre todo para…","ops":["Redactar, ordenar y dar seguimiento","Fijar tus precios","Cobrar por ti","Firmar contratos"],"correcta":0}],"c-ia-freelance-m4":[{"p":"Los derechos de tu trabajo conviene que pasen al cliente…","ops":["Desde la firma","Al recibir el pago total","Nunca","Cuando la IA lo diga"],"correcta":1},{"p":"Si la IA cita un artículo de ley en tu contrato…","ops":["Lo verificas en fuente oficial o con un abogado","Lo dejas","Lo copias en todos tus contratos","Lo cambias de número"],"correcta":0},{"p":"Información confidencial de tu cliente en la IA…","ops":["Se pega completa","Se pega si es poca","Se sustituye por marcadores o se usa una herramienta aprobada por el cliente","Se pega sin nombres pero con cifras reales"],"correcta":2},{"p":"Tu régimen fiscal (RESICO, actividad empresarial u otro) lo decides…","ops":["Con lo que diga la IA","Con tu contador, con tus datos reales","Con lo que usa otro freelancer","Al azar"],"correcta":1},{"p":"Meses de colchón =","ops":["Gastos ÷ ahorro","Ahorro × gastos","Ahorro ÷ gastos fijos del mes","Ingresos ÷ 12"],"correcta":2},{"p":"En tu mejor mes lo más sano es…","ops":["Gastar al ritmo de ese mes","Apartar impuestos y colchón y pagarte sueldo fijo","No apartar nada","Prestar dinero"],"correcta":1},{"p":"Un aviso de aumento de tarifa debe llevar…","ops":["Una cifra de inflación que suene fuerte","Solo el monto nuevo","Una disculpa larga","Monto nuevo, fecha con anticipación y una alternativa"],"correcta":3},{"p":"Para rechazar un proyecto que no es tu especialidad…","ops":["Das una excusa vaga","Lo dices con claridad y recomiendas a alguien","Dejas de contestar","Lo aceptas y lo subcontratas sin avisar"],"correcta":1}],"c-ia-freelance-m5":[{"p":"El reporte de ventas de un cliente con confidencialidad firmada…","ops":["Se pega en la IA para tomar ideas","No se pega; se usan marcadores o nada","Se pega sin el nombre del cliente pero con las cifras","Se comparte con otro cliente"],"correcta":1},{"p":"Un caso de éxito en tu propuesta lleva…","ops":["Cifras que suenen bien","Solo adjetivos","Resultados reales que puedes comprobar, con permiso del cliente","Lo que proponga la IA"],"correcta":2},{"p":"Honorarios $26,000 y gastos $4,500. El anticipo del 50% del total es…","ops":["$15,250","$13,000","$30,500","$2,250"],"correcta":0},{"p":"Si la IA te dice qué impuestos cobrar según tu régimen…","ops":["Lo aplicas","Lo publicas","Lo ignoras siempre","Lo verificas con tu contador"],"correcta":3},{"p":"Una cláusula que te prohíbe mostrar el trabajo en tu portafolio…","ops":["Se acepta sin leer","Se negocia antes de firmar si te importa el portafolio","Es ilegal","No importa"],"correcta":1},{"p":"Para cobrar un saldo atrasado conviene…","ops":["Un mensaje con datos y una propuesta de plan de pago","Exhibir al cliente en redes","Amenazar con demanda sin asesoría","No decir nada"],"correcta":0},{"p":"Tu kit de independiente se revisa…","ops":["Nunca","Solo si pierdes un cliente","Cada trimestre, junto con tu tarifa","Cuando la IA lo pida"],"correcta":2}]}});
